function solve(linha) {
  const result = [];
  let i = 0;
  let current = '';
  let inQuotes = false;

  while (i < linha.length) {
    const ch = linha[i];

    if (inQuotes) {
      if (ch === '"') {
        // Check if next character is also a quote (escaped quote "")
        if (i + 1 < linha.length && linha[i + 1] === '"') {
          current += '"';
          i += 2;
        } else {
          // End of quoted field
          inQuotes = false;
          i++;
        }
      } else {
        current += ch;
        i++;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
        i++;
      } else if (ch === ',') {
        result.push(current);
        current = '';
        i++;
      } else {
        current += ch;
        i++;
      }
    }
  }

  // Push the last field
  result.push(current);

  return result;
}
