function solve(linha) {
  const campos = [];
  let ativo = false;
  let campo = '';
  let i = 0;

  while (i < linha.length) {
    const ch = linha[i];
    if (ativo) {
      if (ch === '"') {
        i++;
        if (i < linha.length && linha[i] === '"') {
          // escaped quote: literal quote inside a quoted field
          campo += '"';
          i++;
        } else {
          // end of quoted field
          ativo = false;
        }
      } else if (ch === ',') {
        // comma outside quotes: end of field
        campos.push(campo);
        campo = '';
        ativo = false;
      } else {
        campo += ch;
      }
    } else {
      // outside quotes
      if (ch === '"') {
        ativo = true;
      } else if (ch === ',') {
        // leading or trailing comma: empty field
        campos.push('');
      } else {
        campo += ch;
      }
    }
    i++;
  }

  // push the last field
  campos.push(campo);

  return campos;
}
