function solve(a, b) {
  const parse = (v) => {
    const [core, pre] = v.split('-');
    const [ma, mi, pa] = core.split('.').map(Number);
    return { major: ma, minor: mi, patch: pa, pre: pre ? pre.split('.') : null };
  };

  const x = parse(a);
  const y = parse(b);

  for (const k of ['major', 'minor', 'patch']) {
    if (x[k] < y[k]) return -1;
    if (x[k] > y[k]) return 1;
  }

  if (!x.pre && !y.pre) return 0;
  if (!x.pre) return 1;
  if (!y.pre) return -1;

  for (let i = 0; i < Math.max(x.pre.length, y.pre.length); i++) {
    const aTok = x.pre[i];
    const bTok = y.pre[i];

    if (aTok === undefined) return -1;
    if (bTok === undefined) return 1;

    const aNum = Number(aTok);
    const bNum = Number(bTok);
    const aIsNum = !Number.isNaN(aNum);
    const bIsNum = !Number.isNaN(bNum);

    if (aIsNum && bIsNum) {
      if (aNum < bNum) return -1;
      if (aNum > bNum) return 1;
    } else if (aIsNum) {
      return -1;
    } else if (bIsNum) {
      return 1;
    } else {
      if (aTok < bTok) return -1;
      if (aTok > bTok) return 1;
    }
  }

  return 0;
}
