function solve(expr) {
  let pos = 0;

  // Tokenize
  function tokenize(s) {
    const tokens = [];
    let i = 0;
    while (i < s.length) {
      if (s[i] === ' ') { i++; continue; }
      if (s[i] === '(') { tokens.push('('); i++; continue; }
      if (s[i] === ')') { tokens.push(')'); i++; continue; }
      if (s[i] === '+' || s[i] === '-' || s[i] === '*' || s[i] === '/') {
        tokens.push(s[i]); i++; continue;
      }
      // Parse number
      let j = i;
      while (j < s.length && /d/.test(s[j])) j++;
      tokens.push(parseInt(s.slice(i, j), 10));
      i = j;
    }
    return tokens;
  }

  const tokens = tokenize(expr);
  let posRef = 0;

  function peek() { return tokens[posRef]; }
  function advance() { return tokens[posRef++]; }

  // parseExpression : [+-] term (('+'|'-'?) term)*
  function parseExpression() {
    let result = parseTerm();
    while (peek() === '+' || peek() === '-') {
      const op = advance();
      const right = parseTerm();
      if (op === '+') result += right;
      else result -= right;
    }
    return result;
  }

  // parseTerm : (('*'|'/') term)*
  function parseTerm() {
    let result = parseFactor();
    while (peek() === '*' || peek() === '/') {
      const op = advance();
      const right = parseFactor();
      if (op === '*') result *= right;
      else result /= right;
    }
    return result;
  }

  // parseFactor : [ '-'? ] primary
  function parseFactor() {
    if (peek() === '-') { advance(); return -parsePrimary(); }
    return parsePrimary();
  }

  // parsePrimary : number | '(' expression ')'
  function parsePrimary() {
    if (typeof peek() === 'number') {
      return advance();
    }
    if (peek() === '(') {
      advance();
      const result = parseExpression();
      advance(); // consume ')'
      return result;
    }
    throw new Error('Unexpected token: ' + peek());
  }

  return parseExpression();
}
