A função está correta. Usa um min-heap para sempre escolher o menor índice disponível, garantindo a ordem topológica lexicograficamente menor. Retorna `null` quando há ciclo.

```js
function solve(n, arestas) {
  const adj = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);

  for (const [a, b] of arestas) {
    adj[a].push(b);
    indeg[b]++;
  }

  const heap = [];
  const heapPush = (v) => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] > heap[i]) {
        [heap[p], heap[i]] = [heap[i], heap[p]];
        i = p;
      } else break;
    }
  };
  const heapPop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let s = i;
        if (l < heap.length && heap[l] < heap[s]) s = l;
        if (r < heap.length && heap[r] < heap[s]) s = r;
        if (s === i) break;
        [heap[i], heap[s]] = [heap[s], heap[i]];
        i = s;
      }
    }
    return top;
  };

  for (let i = 0; i < n; i++) {
    if (indeg[i] === 0) heapPush(i);
  }

  const result = [];
  while (heap.length > 0) {
    const u = heapPop();
    result.push(u);
    for (const v of adj[u]) {
      indeg[v]--;
      if (indeg[v] === 0) heapPush(v);
    }
  }

  return result.length === n ? result : null;
}
