function solve(n, arestas) {
  const adj = Array.from({ length: n }, () => []);
  const inDegree = new Array(n).fill(0);

  for (const [a, b] of arestas) {
    adj[a].push(b);
    inDegree[b]++;
  }

  const minHeap = [];
  for (let i = 0; i < n; i++) {
    if (inDegree[i] === 0) {
      minHeap.push(i);
    }
  }
  minHeap.sort((a, b) => a - b);

  const result = [];

  while (minHeap.length > 0) {
    const node = minHeap.shift();
    result.push(node);

    for (const neighbor of adj[node]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        // Inserir mantendo ordem crescente
        let inserted = false;
        for (let i = 0; i < minHeap.length; i++) {
          if (neighbor < minHeap[i]) {
            minHeap.splice(i, 0, neighbor);
            inserted = true;
            break;
          }
        }
        if (!inserted) {
          minHeap.push(neighbor);
        }
      }
    }
  }

  return result.length === n ? result : null;
}
