    const top = this.arr[0];
    const last = this.arr.pop();
    if (this.arr.length > 0) { this.arr[0] = last; this._sinkDown(0); }
    return top;
  }
  size() { return this.arr.length; }
  _bubbleUp(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.arr[p] > this.arr[i]) { [this.arr[p], this.arr[i]] = [this.arr[i], this.arr[p]]; i = p; }
      else break;
    }
  }
  _sinkDown(i) {
    const n = this.arr.length;
