      let s = i;
      const l = 2 * i + 1, r = 2 * i + 2;
      if (l < n && this.arr[l] < this.arr[s]) s = l;
      if (r < n && this.arr[r] < this.arr[s]) s = r;
      if (s !== i) { [this.arr[i], this.arr[s]] = [this.arr[s], this.arr[i]]; i = s; }
      else break;
