function solve(precos) {
  if (!precos || precos.length < 2) return 0;

  const n = precos.length;

  // Melhor lucro com 1 transação até i (custo mínimo até i)
  const left = new Array(n);
  let min = precos[0];
  for (let i = 1; i < n; i++) {
    min = Math.min(min, precos[i]);
    left[i] = Math.max(left[i - 1], precos[i] - min);
  }

  // Melhor lucro com 1 transação a partir de i (preço máximo a partir de i)
  const right = new Array(n);
  let max = precos[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    max = Math.max(max, precos[i]);
    right[i] = Math.max(right[i + 1], max - precos[i]);
  }

  // Soma dos dois melhores: 1 transação antes + 1 transação depois
  let maxProfit = 0;
  for (let i = 0; i < n; i++) {
    maxProfit = Math.max(maxProfit, left[i] + right[i]);
  }

  return maxProfit;
}
